#!/usr/bin/env python3
import sys, re, json, zipfile, shutil, os

IN_DOCX = "inputs/offer_letter_template.docx"
DATA_JSON = "inputs/employee_data.json"
OUT_DOCX = "output/offer_letter_filled.docx"

def fail(msg):
    sys.stderr.write("ERROR: " + msg + "\n")
    sys.exit(1)

with open(DATA_JSON, encoding="utf-8") as f:
    data = json.load(f)

# Governing field for the conditional
GOV = "RELOCATION_PACKAGE"

# Regex for a single text run <w:t...>...</w:t>
T_RE = re.compile(r'(<w:t\b[^>]*>)(.*?)(</w:t>)', re.S)
# Paragraph splitter
P_RE = re.compile(r'(<w:p\b.*?</w:p>)', re.S)

PLACEHOLDER_RE = re.compile(r'\{\{([A-Z0-9_]+)\}\}')

missing = set()

def xml_escape(s):
    return (s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;'))

def process_paragraph(p_xml, allow_conditional):
    """Merge run texts within paragraph, apply replacements, write back into first run.
    Returns modified paragraph XML."""
    matches = list(T_RE.finditer(p_xml))
    if not matches:
        return p_xml
    # Build combined text (unescaped) and remember spans
    combined = ''.join(m.group(2) for m in matches)
    # Unescape XML entities for matching
    def unesc(s):
        return s.replace('&amp;','&').replace('&lt;','<').replace('&gt;','>').replace('&quot;','"').replace('&apos;',"'")
    combined_u = unesc(combined)

    changed = False
    new_u = combined_u

    # Handle conditional first (only governing field controls it)
    if allow_conditional and '{{IF_RELOCATION}}' in new_u and '{{END_IF_RELOCATION}}' in new_u:
        if GOV not in data:
            missing.add(GOV)
        gov_val = data.get(GOV, None)
        keep = (gov_val == "Yes")  # exact string match, no trimming
        def cond_sub(m):
            return m.group(1) if keep else ''
        new_u = re.sub(r'\{\{IF_RELOCATION\}\}(.*?)\{\{END_IF_RELOCATION\}\}', cond_sub, new_u, flags=re.S)
        changed = True

    # Handle normal placeholders
    def ph_sub(m):
        key = m.group(1)
        if key in ('IF_RELOCATION', 'END_IF_RELOCATION'):
            return m.group(0)  # leave (handled above or n/a)
        if key not in data:
            missing.add(key)
            return m.group(0)
        return data[key]
    new_u2 = PLACEHOLDER_RE.sub(ph_sub, new_u)
    if new_u2 != new_u:
        changed = True
    new_u = new_u2

    if not changed and new_u == combined_u:
        return p_xml

    # Re-escape
    new_esc = xml_escape(new_u)

    # Put all new text into the first w:t; empty the rest (preserve their tags)
    result = []
    last = 0
    first = True
    for m in matches:
        result.append(p_xml[last:m.start()])
        if first:
            # ensure xml:space preserve to keep whitespace
            open_tag = m.group(1)
            if 'xml:space' not in open_tag:
                open_tag = open_tag[:-1] + ' xml:space="preserve">'
            result.append(open_tag + new_esc + m.group(3))
            first = False
        else:
            open_tag = m.group(1)
            if 'xml:space' not in open_tag:
                open_tag = open_tag[:-1] + ' xml:space="preserve">'
            result.append(open_tag + '' + m.group(3))
        last = m.end()
    result.append(p_xml[last:])
    return ''.join(result)

def process_xml(content, allow_conditional):
    parts = P_RE.split(content)
    out = []
    for part in parts:
        if part.startswith('<w:p ') or part.startswith('<w:p>') or (part.startswith('<w:p') and ('</w:p>' in part)):
            out.append(process_paragraph(part, allow_conditional))
        else:
            out.append(part)
    return ''.join(out)

# Read zip, process relevant parts
zin = zipfile.ZipFile(IN_DOCX, 'r')
names = zin.namelist()

targets = ['word/document.xml'] + [n for n in names if re.match(r'word/(header|footer)\d+\.xml$', n)]

new_parts = {}
for n in targets:
    content = zin.read(n).decode('utf-8')
    allow_cond = (n == 'word/document.xml')
    new_parts[n] = process_xml(content, allow_cond)

# Verify no remaining uppercase placeholders in targets
leftover = set()
for n, c in new_parts.items():
    for m in PLACEHOLDER_RE.finditer(c):
        leftover.add((n, m.group(1)))

if missing:
    zin.close()
    fail("Missing required field(s): " + ", ".join(sorted(missing)))

if leftover:
    zin.close()
    fail("Unresolved placeholders remain: " + ", ".join(sorted(f"{k} in {n}" for n,k in leftover)))

# Write output
os.makedirs('output', exist_ok=True)
with zipfile.ZipFile(OUT_DOCX, 'w', zipfile.ZIP_DEFLATED) as zout:
    for item in zin.infolist():
        name = item.filename
        if name in new_parts:
            zout.writestr(item, new_parts[name].encode('utf-8'))
        else:
            zout.writestr(item, zin.read(name))
zin.close()
print("OK: wrote", OUT_DOCX)
